REL_ALL = [("copykiller/", "카피킬러 AI 작성률 낮추기"), ("gptkiller/", "GPT킬러 낮추기"), ("ai-humanizer/", "AI 휴머나이저"), ("lower-ai-rate/", "AI 작성률 낮추기"), ("ai-bypass/", "AI 탐지 우회"),
           ("ai-check/", "AI 작성률 검사"), ("free/", "AI 휴머나이저 무료"), ("thesis/", "논문 AI 작성률"), ("resume/", "자기소개서 AI 작성률"), ("natural/", "AI 티 안 나게")]


REL_NEW = [("humanizing/", "AI 휴머나이징이란"), ("best-ai-humanizer/", "AI 휴머나이징 사이트 추천"), ("ai-converter/", "AI 문장 변환기"),
           ("report/", "레포트 AI 탐지"), ("results/", "실제 측정 결과")]   # 2026.11.21 밤 키워드 50개 반영으로 더한 페이지


def _rel(skip):
    base = [x for x in REL_ALL if x[0] != skip][:7]
    extra = [x for x in REL_NEW if x[0] != skip]
    k = sum(map(ord, skip)) % len(extra) if extra else 0
    return base + (extra[k:] + extra[:k])[:3]


